import { useContext, useState, useEffect, useCallback } from 'react';
import { AuthContext } from '../../context/authContext';
import axios from 'axios';
import './share.scss';
import Image from '../../assets/img.png';
import Map from '../../assets/map.png';
import Friend from '../../assets/friend.png';

const Share = () => {
  const { currentUser } = useContext(AuthContext);
  const [desc, setDesc] = useState('');
  const [file, setFile] = useState(null);
  const [filePreview, setFilePreview] = useState(null);
  const [location, setLocation] = useState('');
  const [friends, setFriends] = useState([]);
  const [taggedFriends, setTaggedFriends] = useState([]);
  const [showFriendsDropdown, setShowFriendsDropdown] = useState(false);
  const [error, setError] = useState(null);
  const [loading, setLoading] = useState(false);

  console.log('Share: Initial render, currentUser=', currentUser ? JSON.stringify(currentUser, null, 2) : 'null');
  console.log('Share: sessionStorage.accessToken=', sessionStorage.getItem('accessToken') || 'null');

  const getProfilePictureUrl = (profilePicture) => {
    if (!profilePicture) {
      console.log('Share: No profile picture provided, using fallback');
      return 'https://images.pexels.com/photos/3228727/pexels-photo-3228727.jpeg?auto=compress&cs=tinysrgb&w=1600';
    }
    if (profilePicture.startsWith('http')) {
      console.log('Share: Using external profile picture URL:', profilePicture);
      return profilePicture;
    }
    // Handle both post_upload and profile_upload paths
    const normalizedPath = profilePicture
      .replace(/^\/(Uploads|post_upload)\//i, '/$1/')
      .replace(/^\/(post_upload|profile_upload)\//i, '/$1/');
    const url = `http://localhost:5000${normalizedPath}?t=${new Date().getTime()}`;
    console.log('Share: Profile picture URL:', url);
    return url;
  };

  const fetchFriends = useCallback(async () => {
    const token = sessionStorage.getItem('accessToken');
    if (!token) {
      console.error('Share: No accessToken found in sessionStorage');
      setError('Please log in to fetch friends.');
      return;
    }

    try {
      console.log(`Share: Fetching friends for user ID: ${currentUser._id}`);
      const res = await axios.get(`http://localhost:5000/api/users/${currentUser._id}`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      console.log('Share: Fetched friends=', JSON.stringify(res.data.friends, null, 2));
      setFriends(res.data.friends || []);
    } catch (err) {
      console.error('Share: Error fetching friends:', err.message);
      console.error('Share: Error details:', {
        status: err.response?.status,
        data: JSON.stringify(err.response?.data, null, 2),
      });
      setError(err.response?.data?.message || 'Failed to load friends.');
    }
  }, [currentUser]);

  useEffect(() => {
    if (currentUser) {
      fetchFriends();
    }
  }, [currentUser, fetchFriends]);

  useEffect(() => {
    if (file) {
      const fileType = file.type;
      const maxSize = 5 * 1024 * 1024; // 5MB
      if (file.size > maxSize) {
        console.error('Share: File size exceeds 5MB:', file.size);
        setError('File size must be less than 5MB.');
        setFile(null);
        setFilePreview(null);
        return;
      }
      if (fileType.startsWith('image/') || fileType.startsWith('video/')) {
        const url = URL.createObjectURL(file);
        setFilePreview({ url, type: fileType.startsWith('image/') ? 'image' : 'video' });
        console.log('Share: File preview set:', { url, type: fileType });
      } else {
        console.error('Share: Invalid file type:', fileType);
        setError('Please select an image or video file.');
        setFile(null);
        setFilePreview(null);
      }
    } else {
      setFilePreview(null);
    }

    return () => {
      if (filePreview) {
        URL.revokeObjectURL(filePreview.url);
      }
    };
  }, [file, filePreview]);

  const toggleFriendTag = (friendId) => {
    setTaggedFriends((prev) =>
      prev.includes(friendId)
        ? prev.filter((id) => id !== friendId)
        : [...prev, friendId]
    );
    console.log('Share: Tagged friends updated:', taggedFriends);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!desc && !file && !location && taggedFriends.length === 0) {
      console.error('Share: No content provided for post');
      setError('Please provide a description, image/video, location, or tag friends.');
      return;
    }

    setLoading(true);
    setError(null);

    const formData = new FormData();
    formData.append('desc', desc || '');
    formData.append('userId', currentUser._id);
    formData.append('name', currentUser.name || '');
    formData.append('profilePicture', currentUser.profilePicture || '');
    if (file) formData.append('media', file);
    if (location) formData.append('location', location);
    if (taggedFriends.length > 0) formData.append('taggedFriends', JSON.stringify(taggedFriends));

    console.log('Share: FormData entries:', Array.from(formData.entries()));

    try {
      const token = sessionStorage.getItem('accessToken');
      if (!token) {
        console.error('Share: No accessToken found in sessionStorage');
        throw new Error('Please log in to share a post.');
      }
      console.log('Share: Posting to http://localhost:5000/api/posts');
      const res = await axios.post('http://localhost:5000/api/posts', formData, {
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });
      console.log('Share: Post created successfully:', JSON.stringify(res.data, null, 2));
      setDesc('');
      setFile(null);
      setFilePreview(null);
      setLocation('');
      setTaggedFriends([]);
      window.dispatchEvent(new Event('newPost'));
      alert('Post shared successfully!');
    } catch (err) {
      console.error('Share: Error creating post:', err.message);
      console.error('Share: Error details:', {
        status: err.response?.status,
        data: JSON.stringify(err.response?.data, null, 2),
      });
      let errorMessage = 'Failed to create post. Please try again.';
      if (err.response?.status === 401) {
        errorMessage = 'Session expired. Please log in again.';
        sessionStorage.removeItem('accessToken');
        sessionStorage.removeItem('user');
      } else if (err.response?.status === 400) {
        errorMessage = err.response.data.message || 'Invalid post data.';
      }
      setError(errorMessage);
    } finally {
      setLoading(false);
      console.log('Share: handleSubmit completed, loading=', false);
    }
  };

  return (
    <div className="share">
      <div className="container">
        <div className="top">
          <img
            src={getProfilePictureUrl(currentUser?.profilePicture)}
            alt={`${currentUser?.name}'s profile`}
            className="profile-img"
            onError={(e) => {
              console.error('Share: Profile picture load error:', e);
              e.target.src = 'https://images.pexels.com/photos/3228727/pexels-photo-3228727.jpeg?auto=compress&cs=tinysrgb&w=1600';
            }}
          />
          <input
            type="text"
            placeholder={`What's on your mind ${currentUser?.name || ''}?`}
            value={desc}
            onChange={(e) => setDesc(e.target.value)}
            disabled={loading}
          />
        </div>
        {filePreview && (
          <div className="preview">
            {filePreview.type === 'image' ? (
              <img src={filePreview.url} alt="Preview" className="preview-media" />
            ) : (
              <video src={filePreview.url} controls className="preview-media" />
            )}
            <button
              className="remove-media"
              onClick={() => {
                setFile(null);
                setFilePreview(null);
              }}
            >
              Remove
            </button>
          </div>
        )}
        {location && (
          <div className="location">
            <span>Location: {location}</span>
            <button
              className="remove-location"
              onClick={() => setLocation('')}
            >
              Remove
            </button>
          </div>
        )}
        {taggedFriends.length > 0 && (
          <div className="tagged-friends">
            <span>
              Tagged:{' '}
              {taggedFriends
                .map((id) => friends.find((f) => f._id === id)?.name || 'Unknown')
                .join(', ')}
            </span>
            <button
              className="remove-tagged"
              onClick={() => setTaggedFriends([])}
            >
              Clear Tags
            </button>
          </div>
        )}
        <hr />
        <div className="bottom">
          <div className="left">
            <input
              type="file"
              id="file"
              accept="image/*,video/*"
              style={{ display: 'none' }}
              onChange={(e) => setFile(e.target.files[0])}
            />
            <label htmlFor="file">
              <div className="item">
                <img src={Image} alt="Add Media" />
                <span>Add Image/Video</span>
              </div>
            </label>
            <div className="item" onClick={() => {
              const loc = prompt('Enter location (e.g., New York, NY):');
              if (loc) setLocation(loc);
            }}>
              <img src={Map} alt="Add Place" />
              <span>Add Place</span>
            </div>
            <div className="item" onClick={() => setShowFriendsDropdown(!showFriendsDropdown)}>
              <img src={Friend} alt="Tag Friends" />
              <span>Tag Friends</span>
            </div>
            {showFriendsDropdown && (
              <div className="friends-dropdown">
                {friends.length > 0 ? (
                  friends.map((friend) => (
                    <div
                      key={friend._id}
                      className={`friend-option ${taggedFriends.includes(friend._id) ? 'selected' : ''}`}
                      onClick={() => toggleFriendTag(friend._id)}
                    >
                      <img
                        src={getProfilePictureUrl(friend.profilePicture)}
                        alt={`${friend.name}'s profile`}
                        className="friend-avatar"
                        onError={(e) => {
                          e.target.src = 'https://images.pexels.com/photos/3228727/pexels-photo-3228727.jpeg?auto=compress&cs=tinysrgb&w=1600';
                        }}
                      />
                      <span>{friend.name}</span>
                    </div>
                  ))
                ) : (
                  <p>No friends to tag.</p>
                )}
              </div>
            )}
          </div>
          <div className="right">
            <button onClick={handleSubmit} disabled={loading}>
              {loading ? 'Sharing...' : 'Share'}
            </button>
          </div>
        </div>
        {error && <p className="error">{error}</p>}
      </div>
    </div>
  );
};

export default Share;
